func EvaluateCoverageGateWithAuthorityPreflight(prd PRDDocument, adrIndex ADRIndex, adrs []ParsedADR, ledger TDDLedger, traceability TraceabilityMatrix, authorityFindings []LintSummaryFinding, knownTDDIDs ...map[string]bool) CoverageGateEvaluation {
	return ApplyCoverageGateAuthorityPreflight(EvaluateCoverageGate(prd, adrIndex, adrs, ledger, traceability, knownTDDIDs...), authorityFindings)
}

func ApplyCoverageGateAuthorityPreflight(out CoverageGateEvaluation, findings []LintSummaryFinding) CoverageGateEvaluation {
	authorityFindings := coverageGateAuthorityFindings(findings)
	status := "pass"
	if len(authorityFindings) > 0 {
		status = "blocked"
		out.Status = "blocked"
		for _, finding := range authorityFindings {
			out.Findings = append(out.Findings, CoverageGateFinding{
				Kind:      strings.TrimSpace(finding.Code),
				Criterion: "authority_preflight",
				Message:   strings.TrimSpace(finding.Message),
				File:      strings.TrimSpace(finding.Path),
				Severity:  "error",
			})
			out.Blockers = append(out.Blockers, CoverageGateBlocker{
				Kind:      strings.TrimSpace(finding.Code),
				Criterion: "authority_preflight",
				Message:   strings.TrimSpace(finding.Message),
				File:      strings.TrimSpace(finding.Path),
			})
		}
	}
	out.Criteria = append(out.Criteria, CoverageGateCriterion{
		Key:      "authority_preflight",
		Required: true,
		Status:   status,
		Details:  "canonical product authority lint findings must be resolved before coverage can pass",
	})
	sort.Slice(out.Criteria, func(i, j int) bool { return out.Criteria[i].Key < out.Criteria[j].Key })
	sort.Slice(out.Findings, func(i, j int) bool {
		if out.Findings[i].Criterion == out.Findings[j].Criterion {
			return out.Findings[i].Kind < out.Findings[j].Kind
		}
		return out.Findings[i].Criterion < out.Findings[j].Criterion
	})
	sort.Slice(out.Blockers, func(i, j int) bool {
		if out.Blockers[i].Criterion == out.Blockers[j].Criterion {
			return out.Blockers[i].Kind < out.Blockers[j].Kind
		}
		return out.Blockers[i].Criterion < out.Blockers[j].Criterion
	})
	return out
}

func coverageGateAuthorityFindings(findings []LintSummaryFinding) []LintSummaryFinding {
	out := make([]LintSummaryFinding, 0, len(findings))
	for _, finding := range findings {
		if coverageGateAuthorityFinding(finding) {
			if strings.TrimSpace(finding.Code) == "" {
				finding.Code = "coverage_authority_preflight_unresolved"
			}
			out = append(out, finding)
		}
	}
	return out
}

func coverageGateAuthorityFinding(finding LintSummaryFinding) bool {
	code := strings.ToLower(strings.TrimSpace(finding.Code))
	path := strings.TrimSpace(finding.Path)
	if strings.HasPrefix(code, "adr_supersession_") {
		return true
	}
	if strings.HasPrefix(code, "obsidian_") && (strings.Contains(code, "stale_status") || strings.Contains(code, "checklist_drift")) {
		return true
	}
	switch code {
	case "broken_link", "parse_error", "missing_file", "symlink_file":
		return coverageGateAuthorityPath(path)
	default:
		return false
	}
}

func coverageGateAuthorityPath(path string) bool {
	clean := strings.TrimPrefix(strings.ReplaceAll(strings.TrimSpace(path), "\\", "/"), "./")
	return clean == "prd.md" ||
		clean == "tdd.json" ||
		clean == "adrs/index.json" ||
		clean == "evidence/traceability_matrix.json" ||
		strings.HasPrefix(clean, "adrs/")
}

