func TestCoverageGateAuthorityPreflightCarriesLintFindings(t *testing.T) {
	eval := ApplyCoverageGateAuthorityPreflight(coverageGateEvalWithZeroInvariants("unit"), []LintSummaryFinding{
		{Code: "adr_supersession_broken_ref", Path: "adrs/index.json", Message: "ADR index references a missing superseded ADR"},
	})
	if eval.Status != "blocked" {
		t.Fatalf("expected blocked, got %q", eval.Status)
	}
	foundCriterion := false
	for _, criterion := range eval.Criteria {
		if criterion.Key == "authority_preflight" && criterion.Status == "blocked" {
			foundCriterion = true
			break
		}
	}
	if !foundCriterion {
		t.Fatalf("expected blocked authority_preflight criterion, got %#v", eval.Criteria)
	}
	if len(eval.Blockers) == 0 || len(eval.Findings) == 0 {
		t.Fatalf("expected authority blockers and findings, got blockers=%#v findings=%#v", eval.Blockers, eval.Findings)
	}
	foundBlocker := false
	foundFinding := false
	for _, blocker := range eval.Blockers {
		if blocker.Criterion == "authority_preflight" && blocker.Kind == "adr_supersession_broken_ref" && blocker.File == "adrs/index.json" && strings.Contains(blocker.Message, "missing superseded ADR") {
			foundBlocker = true
		}
	}
	for _, finding := range eval.Findings {
		if finding.Criterion == "authority_preflight" && finding.Kind == "adr_supersession_broken_ref" && finding.File == "adrs/index.json" && finding.Severity == "error" {
			foundFinding = true
		}
	}
	if !foundBlocker || !foundFinding {
		t.Fatalf("expected typed authority blocker/finding, blockers=%#v findings=%#v", eval.Blockers, eval.Findings)
	}
}

func TestCoverageGateAuthorityFindingCoversCanonicalLintMatrix(t *testing.T) {
	tests := []struct {
		name string
		in   LintSummaryFinding
		want bool
	}{
		{"prd parse", LintSummaryFinding{Code: "parse_error", Path: "prd.md"}, true},
		{"adr broken link", LintSummaryFinding{Code: "broken_link", Path: "adrs/ADR-1.md"}, true},
		{"traceability missing", LintSummaryFinding{Code: "missing_file", Path: "evidence/traceability_matrix.json"}, true},
		{"tdd parse", LintSummaryFinding{Code: "parse_error", Path: "tdd.json"}, true},
		{"adr supersession", LintSummaryFinding{Code: "adr_supersession_non_reciprocal", Path: "adrs/index.json"}, true},
		{"obsidian status divergence", LintSummaryFinding{Code: "obsidian_stale_status", Path: ObsidianProductWorkflowPath}, true},
		{"read error is not authority", LintSummaryFinding{Code: "read_error", Path: "prd.md"}, false},
		{"unrelated stale context", LintSummaryFinding{Code: "stale_context", Path: "workflow_state.json"}, false},
		{"unrelated report parse", LintSummaryFinding{Code: "parse_error", Path: "reports/review.json"}, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := coverageGateAuthorityFinding(tt.in); got != tt.want {
				t.Fatalf("coverageGateAuthorityFinding(%#v) = %v, want %v", tt.in, got, tt.want)
			}
		})
	}
}
